import { expect, expectStatus, test } from "../../fixtures";

test("A vendor from another tenant is not found by id", { tag: "@VEN-07" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor that exists in the Globex Procurement tenant
  const member = await apiAs("member");
  const globex = await apiAs("otherTenant");
  const foreign = await factory.vendor({ as: "otherTenant" });
  expect((await expectStatus<{ id: string }>(await globex.get(`/api/vendors/${foreign.id}`), 200)).id).toBe(foreign.id);

  // Act: the Northwind member requests that vendor by id
  const response = await member.get(`/api/vendors/${foreign.id}`);

  // Assert
  const body = await expectStatus(response, 404);
  expect(body.error.code).toBe("vendor_not_found");
});
